import sys,numpy as np
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); o=r.get_obs(cameras=['robot0_eye_in_hand'],include_depth=True,video='none'); rgb=o.last['robot0_eye_in_hand']; d=o.depth['robot0_eye_in_hand'];d=d[-1] if d.ndim==3 else d;R,G,B=rgb[:,:,0],rgb[:,:,1],rgb[:,:,2];mask=(R>38)&(R>1.3*G)&(R>1.18*B)&(G<125)&(B<115); roi=np.zeros_like(mask);roi[20:215,50:270]=1;mask &= roi
# largest component
seen=np.zeros_like(mask); comps=[]
for yy,xx in zip(*np.nonzero(mask)):
 if seen[yy,xx]:continue
 st=[(int(yy),int(xx))];seen[yy,xx]=1;a=[]
 while st:
  y,x=st.pop();a.append((y,x))
  for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
   if 0<=ny<240 and 0<=nx<320 and mask[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;st.append((ny,nx))
pix=np.array(max(comps,key=len));T=np.array(o.meta['cameras']['robot0_eye_in_hand']['cam2world_gl']);K=np.array(o.meta['cameras']['robot0_eye_in_hand']['intrinsic_cv']);pts=[]
for y,x in pix:
 z=float(d[y,x]);ray=np.array([(x-K[0,2])/K[0,0],-(y-K[1,2])/K[1,1],-1]);pts.append((T@np.r_[ray*z,1])[:3])
pts=np.array(pts);mu=pts.mean(axis=0); u,s,vh=np.linalg.svd(pts-mu,full_matrices=False);print('n',len(pix),'pix bbox',pix.min(0),pix.max(0),'centroid',pix.mean(0)); print('xyz median',np.median(pts,axis=0),'mean',mu,'singular',s); print('axis',vh[0], 'extent along axis',np.percentile((pts-mu)@vh[0],[5,95])); print('camera right',T[:3,0],'eef',o.meta['proprio']['now'][26:29]);
# Estimate countertop z in nearby RGB pixel patch, excluding detected bottle color
valid=(d>.05)&(d<3)&(~mask); yy,xx=np.where(valid); world=[]
for y,x in zip(yy[::50],xx[::50]):
 ray=np.array([(x-K[0,2])/K[0,0],-(y-K[1,2])/K[1,1],-1]);world.append((T@np.r_[ray*float(d[y,x]),1])[:3])
world=np.array(world);print('nearby sampled world z percentiles',np.percentile(world[:,2],[5,25,50,75,95]));print('timeleft',o.meta['time_left_s'])
